/* cppi::7e302d73a6c6c0c552a02c81beb987e814c58f0ce4301734b7753cfa87806fbb */
select cusip, isin, ticker as issuer_code, issuer_name,coupon_rate as coupon, maturity_date as maturity, issue_date, interest_accrual_date, currency_code, country_code, null as classification_1, null as classification_2, null as classification_3, first_coupon_date, coupon_frequency_code as coupon_freq, inflation_linked_flag as inflation_linked, null as is_green, cppib_sec_id
